//! C4 leave proof in the commit (ABI 24): the statement, the AAD, the
//! committer's filtering and the receiver's verification.

use super::*;
use ed25519_dalek::{Signer as _, SigningKey};
use serde_json::{json, Value};

/// `testing/vectors/c4-leave-proof-v1.json`, regenerated byte for byte by
/// `cargo test --lib leave_proof::tests::print_vector -- --ignored --nocapture`.
const VECTOR: &str = include_str!("../../../../testing/vectors/c4-leave-proof-v1.json");
const GROUP: &[u8] = b"conv_c4_leave";
const SEED: [u8; 32] = [0x5c; 32];
const SECOND_SEED: [u8; 32] = [0x6d; 32];

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn unhex(value: &Value) -> Vec<u8> {
    let text = value.as_str().expect("hex string");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex"))
        .collect()
}

fn device(name: &str) -> MlsDevice {
    MlsDevice::new(
        format!("acct_{name}").as_bytes(),
        format!("dev_{name}").as_bytes(),
    )
    .unwrap()
}

fn add<'a>(key_package: &'a [u8], account: &'a [u8], device: &'a [u8]) -> MemberAdd<'a> {
    MemberAdd {
        key_package,
        account_id: account,
        device_id: device,
    }
}

fn remove<'a>(account: &'a [u8], device: &'a [u8]) -> MemberIdentity<'a> {
    MemberIdentity {
        account_id: account,
        device_id: device,
    }
}

fn pair(name: &str, device: &MlsDevice) -> LeafPair {
    LeafPair {
        account_id: format!("acct_{name}").into_bytes(),
        device_id: format!("dev_{name}").into_bytes(),
        signing_key: device.signing_public_key().to_vec(),
    }
}

/// Alice creates a record group and adds Bob and Carol; all at epoch 1.
fn group() -> (Vec<MlsDevice>, Vec<MlsGroup>) {
    let devices = vec![device("alice"), device("bob"), device("carol")];
    let mut alice_group = devices[0].create_group_with_record(GROUP, b"g0").unwrap();
    let kps: Vec<_> = devices[1..]
        .iter()
        .map(|d| d.create_key_package().unwrap())
        .collect();
    let adds = [
        add(&kps[0], b"acct_bob", b"dev_bob"),
        add(&kps[1], b"acct_carol", b"dev_carol"),
    ];
    let staged = devices[0]
        .stage_commit_with_record(&mut alice_group, &adds, &[None, None], &[], Some(b"r1"))
        .unwrap();
    devices[0].merge_pending_commit(&mut alice_group).unwrap();
    let bob_group = devices[1].join_group(GROUP, &staged.welcome).unwrap();
    let carol_group = devices[2].join_group(GROUP, &staged.welcome).unwrap();
    (devices, vec![alice_group, bob_group, carol_group])
}

/// The AAD of a serialized commit.
fn aad_of(commit: &[u8]) -> Vec<u8> {
    commit_aad(commit).unwrap()
}

fn aad(statements: &[&[u8]]) -> Vec<u8> {
    let parsed: Vec<_> = statements
        .iter()
        .map(|s| LeaveStatement::parse(s).unwrap())
        .collect();
    encode_aad(&parsed).unwrap()
}

#[test]
fn a_newcomer_reads_the_leave_from_the_commit_even_through_a_padded_welcome() {
    let (devices, mut groups) = group();
    let carol_leaves = devices[2].sign_leave(&groups[2]).unwrap();
    assert_eq!(carol_leaves.len(), STATEMENT_BYTES);

    // Bob removes Carol and adds Dave in one commit: the Welcome is padded,
    // which stages more than once, and the AAD must ride on the one sent.
    let dave = device("dave");
    let dave_kp = dave.create_key_package().unwrap();
    let staged = devices[1]
        .stage_commit_proven(
            &mut groups[1],
            &[add(&dave_kp, b"acct_dave", b"dev_dave")],
            &[None],
            &[remove(b"acct_carol", b"dev_carol")],
            Some(b"r2"),
            Some(&aad(&[&carol_leaves])),
        )
        .unwrap();
    assert!(!staged.welcome.is_empty());
    assert_eq!(aad_of(&staged.commit), aad(&[&carol_leaves]));
    // OpenMLS cleared it after staging; it never rides on a later message.
    assert!(groups[1].aad().is_empty());
    devices[1].merge_pending_commit(&mut groups[1]).unwrap();

    let review = devices[0]
        .stage_incoming_commit(&mut groups[0], &staged.commit)
        .unwrap();
    assert_eq!(review.proven, vec![pair("carol", &devices[2])]);
    devices[0]
        .merge_incoming_commit(&mut groups[0], &staged.commit)
        .unwrap();
    let mut dave_group = dave.join_group(GROUP, &staged.welcome).unwrap();

    // Later, a commit made after Dave joined proves a removal he never saw
    // the notice of: Alice removes Bob with Bob's statement.
    let bob_leaves = devices[1].sign_leave(&groups[1]).unwrap();
    let removal = devices[0]
        .stage_commit_proven(
            &mut groups[0],
            &[],
            &[],
            &[remove(b"acct_bob", b"dev_bob")],
            Some(b"r3"),
            Some(&aad(&[&bob_leaves])),
        )
        .unwrap();
    devices[0].merge_pending_commit(&mut groups[0]).unwrap();
    let review = dave
        .stage_incoming_commit(&mut dave_group, &removal.commit)
        .unwrap();
    assert_eq!(review.proven, vec![pair("bob", &devices[1])]);
}

#[test]
fn a_record_free_commit_carries_the_proof_too() {
    let (devices, mut groups) = group();
    let carol_leaves = devices[2].sign_leave(&groups[2]).unwrap();
    let staged = devices[0]
        .stage_commit_proven(
            &mut groups[0],
            &[],
            &[],
            &[remove(b"acct_carol", b"dev_carol")],
            None,
            Some(&aad(&[&carol_leaves])),
        )
        .unwrap();
    devices[0].merge_pending_commit(&mut groups[0]).unwrap();
    let review = devices[1]
        .stage_incoming_commit(&mut groups[1], &staged.commit)
        .unwrap();
    assert_eq!(review.proven, vec![pair("carol", &devices[2])]);
    assert_eq!(review.flags & REVIEW_RECORD_PROPOSAL, 0);
}

#[test]
fn the_committer_drops_statements_that_prove_nothing() {
    let (devices, mut groups) = group();
    let carol_leaves = devices[2].sign_leave(&groups[2]).unwrap();
    let bob_leaves = devices[1].sign_leave(&groups[1]).unwrap();
    let mut forged = LeaveStatement::parse(&carol_leaves).unwrap();
    forged.signature[0] ^= 1;

    // Bob's statement names a leaf this commit keeps; the forged one does
    // not verify: neither goes out, and with none left there is no AAD.
    for proofs in [aad(&[&bob_leaves]), encode_aad(&[forged.clone()]).unwrap()] {
        let staged = devices[0]
            .stage_commit_proven(
                &mut groups[0],
                &[],
                &[],
                &[remove(b"acct_carol", b"dev_carol")],
                Some(b"r2"),
                Some(&proofs),
            )
            .unwrap();
        assert!(aad_of(&staged.commit).is_empty());
        devices[0].clear_pending_commit(&mut groups[0]).unwrap();
    }
    // Only the statement that proves something is kept.
    let staged = devices[0]
        .stage_commit_proven(
            &mut groups[0],
            &[],
            &[],
            &[remove(b"acct_carol", b"dev_carol")],
            Some(b"r2"),
            Some(&aad(&[&bob_leaves, &carol_leaves])),
        )
        .unwrap();
    assert_eq!(aad_of(&staged.commit), aad(&[&carol_leaves]));
    devices[0].clear_pending_commit(&mut groups[0]).unwrap();
    // A malformed list is refused before anything is staged.
    assert_eq!(
        devices[0]
            .stage_commit_proven(
                &mut groups[0],
                &[],
                &[],
                &[remove(b"acct_carol", b"dev_carol")],
                Some(b"r2"),
                Some(b"VCL1\x00"),
            )
            .err(),
        Some(MlsError::InvalidMessage)
    );
    assert!(groups[0].pending_commit().is_none());
    assert!(groups[0].aad().is_empty());
}

#[test]
fn a_statement_is_void_once_its_leaf_changes() {
    let (devices, mut groups) = group();
    let carol_leaves = devices[2].sign_leave(&groups[2]).unwrap();
    // Carol cancels her leave: her self-update replaces her leaf's HPKE key.
    let update = devices[2].stage_self_update(&mut groups[2]).unwrap();
    devices[2].merge_pending_commit(&mut groups[2]).unwrap();
    for i in 0..2 {
        devices[i]
            .process_commit(&mut groups[i], &update.commit)
            .unwrap();
    }
    let staged = devices[0]
        .stage_commit_proven(
            &mut groups[0],
            &[],
            &[],
            &[remove(b"acct_carol", b"dev_carol")],
            Some(b"r2"),
            Some(&aad(&[&carol_leaves])),
        )
        .unwrap();
    assert!(aad_of(&staged.commit).is_empty());
    devices[0].clear_pending_commit(&mut groups[0]).unwrap();
    // And a receiver given the old statement (a committer that skips the
    // check) proves nothing with it.
    let removed = devices[1]
        .member_indices(&groups[1], b"acct_carol", b"dev_carol")
        .unwrap();
    assert!(proven_leaves(&groups[1], &removed, &aad(&[&carol_leaves])).is_empty());
    // A fresh statement from the updated leaf verifies.
    let fresh = devices[2].sign_leave(&groups[2]).unwrap();
    assert_eq!(
        proven_leaves(&groups[1], &removed, &aad(&[&fresh])),
        vec![pair("carol", &devices[2])]
    );
}

#[test]
fn a_statement_from_another_group_proves_nothing() {
    let (devices, groups) = group();
    let other = devices[2].create_group(b"conv_other").unwrap();
    let elsewhere = devices[2].sign_leave(&other).unwrap();
    let removed = devices[1]
        .member_indices(&groups[1], b"acct_carol", b"dev_carol")
        .unwrap();
    // Both are leaf 0 of their group for Carol only if the index matched;
    // force the index to Carol's leaf here so only the group id differs.
    let mut statement = LeaveStatement::parse(&elsewhere).unwrap();
    statement.leaf_index = removed[0].u32();
    assert!(proven_leaves(&groups[1], &removed, &encode_aad(&[statement]).unwrap()).is_empty());
}

#[test]
fn a_malformed_aad_is_never_a_refusal() {
    let (devices, mut groups) = group();
    let carol_leaves = devices[2].sign_leave(&groups[2]).unwrap();
    let removed = devices[0]
        .member_indices(&groups[0], b"acct_carol", b"dev_carol")
        .unwrap();
    let mut trailing = aad(&[&carol_leaves]);
    trailing.push(0);
    let mut doubled = aad(&[&carol_leaves]);
    doubled[4] = 2;
    doubled.extend_from_slice(&carol_leaves);
    for bad in [
        b"".to_vec(),
        b"VCL2".to_vec(),
        b"VCL1\x00".to_vec(),
        b"VCL1\x11".to_vec(),
        trailing,
        doubled,
    ] {
        assert!(parse_aad(&bad).is_none() || bad.is_empty());
        // A crafted commit with this AAD (straight through OpenMLS) is
        // staged and reviewed as one without a proof.
        let id = groups[0].group_id().as_slice().to_vec();
        let commit = devices[0]
            .in_group(&id, || {
                let group = &mut groups[0];
                group.set_aad(bad.clone());
                let bundle = group
                    .commit_builder()
                    .propose_removals(removed.iter().copied())
                    .load_psks(devices[0].provider.storage())
                    .map_err(|_| MlsError::GroupOperation)?
                    .build(
                        devices[0].provider.rand(),
                        devices[0].provider.crypto(),
                        &devices[0].signer,
                        |_| true,
                    )
                    .map_err(|_| MlsError::GroupOperation)?
                    .stage_commit(&devices[0].provider)
                    .map_err(|_| MlsError::GroupOperation)?;
                Ok(bundle.into_messages().0.tls_serialize_detached().unwrap())
            })
            .unwrap();
        devices[0].clear_pending_commit(&mut groups[0]).unwrap();
        assert_eq!(aad_of(&commit), bad);
        let review = devices[1]
            .stage_incoming_commit(&mut groups[1], &commit)
            .unwrap();
        assert!(review.proven.is_empty());
        devices[1].discard_incoming_commit(GROUP).unwrap();
        groups[1] = devices[1].load_group(GROUP).unwrap();
    }
}

#[test]
fn the_aad_encoding_is_strict() {
    let one = LeaveStatement {
        leaf_index: 7,
        signature: [0xA5; 64],
    };
    let two = LeaveStatement {
        leaf_index: 9,
        signature: [0x5A; 64],
    };
    let encoded = encode_aad(&[one.clone(), two.clone()]).unwrap();
    assert_eq!(&encoded[..5], b"VCL1\x02");
    assert_eq!(encoded.len(), 5 + 2 * STATEMENT_BYTES);
    assert_eq!(parse_aad(&encoded).unwrap(), vec![one.clone(), two.clone()]);
    assert!(encode_aad(&[]).is_err());
    assert!(encode_aad(&[one.clone(), one.clone()]).is_err());
    assert!(encode_aad(&vec![one.clone(); MAX_STATEMENTS + 1]).is_err());
    let mut bad_len = encode_aad(std::slice::from_ref(&one)).unwrap();
    bad_len[9] = 63;
    assert!(parse_aad(&bad_len).is_none());
    assert!(LeaveStatement::parse(&one.encode()[..STATEMENT_BYTES - 1]).is_none());
    let sixteen: Vec<_> = (0..16)
        .map(|leaf_index| LeaveStatement {
            leaf_index,
            signature: [1; 64],
        })
        .collect();
    assert_eq!(parse_aad(&encode_aad(&sixteen).unwrap()).unwrap().len(), 16);
}

#[test]
fn the_sign_content_cannot_be_another_domain_of_this_crate() {
    let content = sign_content(&leave_tbs(b"g", 0, &[0x20; 33]).unwrap()).unwrap();
    // varint 23, then the RFC 9420 prefix and this label.
    assert_eq!(content[0], 23);
    assert_eq!(&content[1..24], b"MLS 1.0 VeritraC4Leave1");
    // Every raw signing domain of this crate starts with ASCII "veritra-".
    for domain in [
        crate::c7::LABEL_POST,
        crate::c7::LABEL_REKEY_CHK,
        crate::c7::LABEL_SLOT,
        crate::l1::LABEL_SIG,
        b"veritra-enrollment-proof-v1".as_slice(),
    ] {
        assert!(domain.starts_with(b"veritra-"));
        assert_ne!(domain[0], content[0]);
    }
}

/// The known-answer values: a fixed signing seed stands for a leaf key, and
/// a fixed 32-byte key (TLS-encoded, `opaque<V>`) for its HPKE key.
fn vector_values() -> Value {
    let group_id = b"conv_vector".to_vec();
    let mut encryption_key = vec![32u8];
    encryption_key.extend((0..32u8).map(|i| i.wrapping_mul(7).wrapping_add(3)));
    let statement_for = |seed: &[u8; 32], leaf_index: u32| {
        let key = SigningKey::from_bytes(seed);
        let tbs = leave_tbs(&group_id, leaf_index, &encryption_key).unwrap();
        let content = sign_content(&tbs).unwrap();
        let signature = key.sign(&content).to_bytes();
        let statement = LeaveStatement {
            leaf_index,
            signature,
        };
        (key, tbs, content, statement)
    };
    let (key, tbs, content, first) = statement_for(&SEED, 3);
    let (_, _, _, second) = statement_for(&SECOND_SEED, 5);
    json!({
        "name": "c4-leave-proof-v1",
        "description": "C4 leave proof in the commit (crypto ABI 24, docs/crypto.md). LeaveTBS = VL(group_id) || u32 leaf_index || EncryptionKey (TLS opaque<V>); the leaf signature key signs RFC 9420 SignContent(\"MLS 1.0 VeritraC4Leave1\", LeaveTBS) with Ed25519. statement = u32 leaf_index || u16 64 || signature; commit AAD = \"VCL1\" || u8 count (1..16) || statements with distinct leaves. Seeds are fixed test values; regenerate with the ignored Rust test leave_proof::tests::print_vector. Every malformed_aad proves nothing.",
        "label": std::str::from_utf8(LEAVE_LABEL).unwrap(),
        "group_id_hex": hex(&group_id),
        "leaf_index": 3,
        "encryption_key_hex": hex(&encryption_key),
        "signing_seed_hex": hex(&SEED),
        "signing_public_hex": hex(key.verifying_key().as_bytes()),
        "leave_tbs_hex": hex(&tbs),
        "sign_content_hex": hex(&content),
        "signature_hex": hex(&first.signature),
        "statement_hex": hex(&first.encode()),
        "second_statement_hex": hex(&second.encode()),
        "aad_hex": hex(&encode_aad(&[first.clone(), second.clone()]).unwrap()),
        "malformed_aad_hex": [
            "",
            hex(b"VCL2"),
            hex(b"VCL1\x00"),
            hex(&[b"VCL1\x11".as_slice(), &first.encode()].concat()),
            hex(&[b"VCL1\x01".as_slice(), &first.encode(), &[0]].concat()),
            hex(&[b"VCL1\x02".as_slice(), &first.encode(), &first.encode()].concat()),
            hex(&[b"VCL1\x01".as_slice(), &first.encode()[..STATEMENT_BYTES - 1]].concat()),
        ],
    })
}

#[test]
#[ignore = "prints testing/vectors/c4-leave-proof-v1.json"]
fn print_vector() {
    println!(
        "{}",
        serde_json::to_string_pretty(&vector_values()).unwrap()
    );
}

#[test]
fn shared_vector_matches() {
    let vector: Value = serde_json::from_str(VECTOR).unwrap();
    assert_eq!(vector, vector_values());
    // The signature verifies with the public key as a receiver checks it.
    let key: [u8; 32] = unhex(&vector["signing_public_hex"]).try_into().unwrap();
    let signature: [u8; 64] = unhex(&vector["signature_hex"]).try_into().unwrap();
    VerifyingKey::from_bytes(&key)
        .unwrap()
        .verify_strict(
            &unhex(&vector["sign_content_hex"]),
            &Signature::from_bytes(&signature),
        )
        .unwrap();
    for bad in vector["malformed_aad_hex"].as_array().unwrap() {
        assert!(parse_aad(&unhex(bad)).is_none(), "{bad}");
    }
    assert_eq!(parse_aad(&unhex(&vector["aad_hex"])).unwrap().len(), 2);
}
